using System;using System.IO;using System.Linq;using System.Windows.Forms;using System.Threading.Tasks;using SargasPC;
namespace Sargon.Setup {public sealed class PcScanWindow:Form {
 readonly CheckedListBox drives=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true};readonly NumericUpDown hours=new NumericUpDown{Minimum=6,Maximum=168,Value=24,Width=75};readonly CheckBox battery=new CheckBox{Text="Nauji darbai tik prijungus maitinimą",AutoSize=true},cpu=new CheckBox{Text="Atidėti esant didelei CPU apkrovai",AutoSize=true},economy=new CheckBox{Text="Taupus režimas (10 s tarp aplankų)",AutoSize=true};readonly CheckBox cache=new CheckBox{Text="Naudoti patvirtintą ankstesnį rezultatą",AutoSize=true};readonly CheckBox restart=new CheckBox{Text="Pradėti naują ciklą (ankstesnę eigą archyvuoti)",AutoSize=true};readonly TextBox report=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both};readonly Button apply=new Button{Text="Išsaugoti ir pradėti / tęsti",Width=290,Height=42},refresh=new Button{Text="Atnaujinti eigą",Width=170,Height=42},export=new Button{Text="Eksportuoti ataskaitą…",Width=220,Height=42};readonly Timer timer=new Timer{Interval=10000};PcScanSettings settings;bool working;
 public PcScanWindow(bool fixture=false){Text="SARGON — diskų ClamAV patikra";Width=940;Height=850;MinimumSize=new System.Drawing.Size(820,730);Font=new System.Drawing.Font("Segoe UI",11);var table=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=1,RowCount=6};foreach(int height in new[]{105,120,170,50})table.RowStyles.Add(new RowStyle(SizeType.Absolute,height));table.RowStyles.Add(new RowStyle(SizeType.Percent,100));table.RowStyles.Add(new RowStyle(SizeType.Absolute,55));table.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Pasirinkite vietinius diskus. ClamAV tikrins aplankus paeiliui; eiga tęsiama po Windows paleidimo. Nepasiekiamos vietos ir variklio ribos rodomos suvestinėje. Tai periodinis skenavimas; failai prieš paleidimą neblokuojami. Keičiant diskus pradedama nauja eilė, ankstesnis planas išsaugomas."},0,0);table.Controls.Add(drives,0,1);var options=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};options.Controls.AddRange(new Control[]{new Label{Text="Po ciklo (val.):",Width=145,Height=30},hours,battery,cpu,economy,cache,restart});table.Controls.Add(options,0,2);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};buttons.Controls.AddRange(new Control[]{apply,refresh,export});table.Controls.Add(buttons,0,3);table.Controls.Add(report,0,4);table.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Radinius peržiūrėkite SARGON → Paslaugos radinių valdymas. Automatinio originalų šalinimo nėra."},0,5);Controls.Add(table);
  if(fixture){settings=new PcScanSettings{Roots=new[]{"C:\\"}};drives.Items.Add("C:\\",true);apply.Enabled=false;report.Text="Bandymo peržiūra — native veiksmai nevykdomi.";}else{try{settings=Manager.ReadScanSettings();foreach(var d in DriveInfo.GetDrives()){try{if(d.IsReady&&(d.DriveType==DriveType.Fixed||d.DriveType==DriveType.Removable))drives.Items.Add(d.RootDirectory.FullName,settings.Roots!=null&&settings.Roots.Contains(d.RootDirectory.FullName,StringComparer.OrdinalIgnoreCase));}catch(IOException){}}foreach(string root in settings.Roots??new string[0])if(!drives.Items.Cast<string>().Contains(root,StringComparer.OrdinalIgnoreCase))drives.Items.Add(root,true);hours.Value=Math.Max(6,Math.Min(168,settings.PeriodHours));battery.Checked=settings.PauseOnBattery;cpu.Checked=settings.PauseWhenBusy;economy.Checked=settings.StepDelaySeconds>=10;cache.Checked=settings.UseCleanCache;LoadReport();}catch(Exception e){report.Text="Parengtis nepatvirtinta: "+Data.Clean(e.Message);apply.Enabled=false;}}
  refresh.Click+=(s,e)=>{if(!fixture)LoadReport();};export.Click+=(s,e)=>{using(var file=new SaveFileDialog{Filter="Teksto ataskaita|*.txt",FileName="SARGON_disku_patikra.txt"})if(file.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(file.FileName,report.Text,new System.Text.UTF8Encoding(true));}catch(IOException error){MessageBox.Show(this,Data.Clean(error.Message));}};
  apply.Click+=async(s,e)=>{if(working||fixture)return;var next=new PcScanSettings{Roots=drives.CheckedItems.Cast<string>().ToArray(),PeriodHours=(int)hours.Value,StepDelaySeconds=economy.Checked?10:1,PauseOnBattery=battery.Checked,PauseWhenBusy=cpu.Checked,UseCleanCache=cache.Checked,AutomaticUpdates=settings.AutomaticUpdates,DetectionControl=settings.DetectionControl};try{PcScanPolicy.Validate(next);}catch(IOException error){MessageBox.Show(this,error.Message);return;}if(MessageBox.Show(this,"Bus pakeistos paslaugos diskų ir grafiko nuostatos bei pradėta arba tęsiama patikra. Procesas gali užtrukti; jau vykdomam aplankui leidžiama sustoti. Tęsti?","Diskų patikra",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;bool newCycle=restart.Checked;working=true;apply.Enabled=refresh.Enabled=drives.Enabled=false;report.Text="Ruošiama diskų patikra…";try{await Task.Run(()=>Manager.ConfigureScan(next,message=>{if(!IsDisposed)BeginInvoke((Action)(()=>report.AppendText("\r\n"+message)));},newCycle));settings=next;restart.Checked=false;report.AppendText("\r\nUžklausa perduota. Spauskite „Atnaujinti eigą“; paslauga dirba ir uždarius šį langą.");}catch(Exception error){report.AppendText("\r\nNEPATVIRTINTA: "+Data.Clean(error.Message));}finally{working=false;apply.Enabled=refresh.Enabled=drives.Enabled=true;}};
  timer.Tick+=(s,e)=>{if(!working&&!fixture)LoadReport();};Shown+=(s,e)=>{if(!fixture)timer.Start();};FormClosing+=(s,e)=>{if(working){e.Cancel=true;return;}timer.Stop();};FormClosed+=(s,e)=>timer.Dispose();
 }
 void LoadReport(){try{report.Text=Manager.ScanReport();}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException){report.Text="Eiga neperskaityta: "+Data.Clean(e.Message)+"\r\nTai nėra užbaigtos patikros ar saugumo patvirtinimas.";}}
}}
